#!/usr/bin/env node
/**
 * index.mjs — regenerate SCREEN-INDEX.md: route → page file → covering lanes.
 *
 * WHY THIS EXISTS
 *   Every pass used to spend its first minutes re-deriving "which file backs this
 *   screen, and which lane covers it" by reading the tree. That knowledge is
 *   static between changes, so it belongs in a generated file, not in recon.
 *
 * The output is best-effort derived from the router sources (static imports and
 * React.lazy imports plus the route table) and the lane coverage map. It is a
 * navigation aid, not an authority: the router is the authority.
 *
 * Usage: node scripts/dev/index.mjs
 */
import fs from 'node:fs';
import { matchAny } from './lib.mjs';

const ROUTER_FILES = ['src/router/index.tsx', 'src/router.tsx'].filter((f) => fs.existsSync(f));
const laneMap = JSON.parse(fs.readFileSync('scripts/dev/lane-map.json', 'utf8'));
const lanes = Object.keys(laneMap.lanes);

// component name → source file
const componentFile = {};
// route path → component name
const routeComponent = [];

for (const file of ROUTER_FILES) {
  const src = fs.readFileSync(file, 'utf8');

  // `import Page from "..."`, and the same default import alongside named exports:
  // `import Page, { Helper } from "..."`. The second form was invisible here, so a screen whose
  // page and its redirect shared one import silently dropped out of the index.
  for (const m of src.matchAll(/import\s+(\w+)\s*(?:,\s*\{[^}]*\})?\s+from\s+["']([^"']+)["']/g)) {
    if (m[2].startsWith('@/')) componentFile[m[1]] = m[2].replace('@/', 'src/');
  }
  // Named exports used as route elements (`SupplierDetailRedirect`): same file, different export.
  // They were left out entirely, so a kept-alive old address had no row of its own.
  for (const m of src.matchAll(/import\s+(?:\w+\s*,\s*)?\{([^}]*)\}\s+from\s+["']([^"']+)["']/g)) {
    if (!m[2].startsWith('@/')) continue;
    for (const part of m[1].split(',')) {
      const name = part.trim().split(/\s+as\s+/).pop().trim();
      if (name && !componentFile[name]) componentFile[name] = m[2].replace('@/', 'src/');
    }
  }
  for (const m of src.matchAll(/const\s+(\w+)\s*=\s*React\.lazy\(\s*\(\)\s*=>\s*import\(\s*["']([^"']+)["']/g)) {
    if (m[2].startsWith('@/')) componentFile[m[1]] = m[2].replace('@/', 'src/');
  }

  // Each `path: "..."` with the first JSX element that follows it, up to the NEXT `path:`.
  // A bounded window (300, then 1200 chars) was a guess at where a route ends, and a route whose
  // next sibling sat further away — the companies block, followed by a long commented section —
  // silently vanished from the index. The next `path:` is the real boundary: a route declares its
  // element before the next route begins, so the search can never borrow a later screen's element.
  for (const m of src.matchAll(/path:\s*["']([^"']*)["']([\s\S]*?)(?=path:|$)/g)) {
    const [, route, tail] = m;
    const el = tail.match(/element:\s*<\s*([A-Za-z_$][\w$]*)/) || tail.match(/<\s*([A-Za-z_$][\w$]*)\s*\/>/);
    if (el) routeComponent.push({ route, component: el[1] });
  }
}

const seen = new Set();
const rows = [];
for (const { route, component } of routeComponent) {
  const file = componentFile[component];
  if (!file || !route || seen.has(`${route}|${file}`)) continue;
  seen.add(`${route}|${file}`);
  const covering = lanes.filter((l) => matchAny(file, laneMap.lanes[l]));
  rows.push({ route, component, file, covering });
}

const lines = [
  '# Screen index (generated)',
  '',
  `Generated by \`node scripts/dev/index.mjs\` from ${ROUTER_FILES.join(', ')} and \`scripts/dev/lane-map.json\`.`,
  'Do not hand-edit — re-run the generator after router changes. The router is the authority;',
  'this file exists so an impact map starts from a lookup instead of fresh reconnaissance.',
  '',
  '| route | component | file | covering E2E lanes |',
  '|---|---|---|---|',
  ...rows.map((r) => `| \`${r.route}\` | ${r.component} | \`${r.file}\` | ${r.covering.join(', ') || '—'} |`),
  '',
  '## Regenerate',
  '',
  '```bash',
  'node scripts/dev/index.mjs',
  '```',
  '',
];

fs.writeFileSync('SCREEN-INDEX.md', lines.join('\n'));
console.log(`SCREEN-INDEX.md written: ${rows.length} route(s) mapped from ${ROUTER_FILES.length} router file(s).`);
